def count_special_numbers(n, k):
    def count_bits(x):
        return bin(x).count('1')

    def dp(n, k):
        if n == 0 or k == 0:
            return 0
        if k == 1:
            return 1 if n > 1 else 0

        memo = {}

        def dfs(num, remaining_k):
            if (num, remaining_k) in memo:
                return memo[(num, remaining_k)]

            if remaining_k == 0:
                return 1 if num == 1 else 0

            if num == 0:
                return 0

            count = 0
            for i in range(num.bit_length()):
                if num & (1 << i):
                    new_num = num ^ (1 << i)
                    count += dfs(new_num, remaining_k - 1)
                    count %= MOD

            memo[(num, remaining_k)] = count
            return count

        return dfs(n, k)

    n = int(n, 2)
    return dp(n, k)

