def count_special_numbers(n, k):
    def count_bits(x):
        return bin(x).count('1')

    def dp(i, j, tight):
        if i == len(n):
            return j == 1
        if (i, j, tight) in memo:
            return memo[(i, j, tight)]

        res = 0
        limit = int(n[i]) if tight else 1
        for d in range(limit + 1):
            new_tight = tight and (d == limit)
            new_j = j - (1 if d == 1 else 0)
            if new_j >= 0:
                res = (res + dp(i + 1, new_j, new_tight)) % MOD

        memo[(i, j, tight)] = res
        return res

    memo = {}
    return dp(0, k, True)

